func (c *Command) Append(ctx context.Context, event any) error {
	started := time.Now()
	err := c.store.Append(ctx, event)
	rows := 1
	if err != nil {
		rows = 0
	}
	c.observe(AppendObservation{EventType: fmt.Sprintf("%T", event), Duration: time.Since(started), Rows: rows, Err: err})
	return err
}

func (e *DeviationEvent) Validate() error {
	if (e.ActivityGroupID == nil || *e.ActivityGroupID <= 0) && (e.InstanceID == nil || *e.InstanceID <= 0) && (e.StaffShiftID == nil || *e.StaffShiftID <= 0) {
		return errors.New("activity_group_id, instance_id or staff_shift_id is required")
	}
	if e.OccurrenceDate.IsZero() {
		return errors.New("occurrence_date is required")
	}
	if e.EventType == "" {
		return errors.New("event_type is required")
	}
	return nil
}
